        ap(ch(2, "¿Amor de sí o amor propio?", "Alguien se compra un auto que no necesita para que los vecinos vean que le va mejor que a ellos.", "amor propio",
           ["amor propio", "amor de sí"], "Es relativo: busca ser preferido, depende de la comparación y nunca se satisface.")),
        ap(ch(2, "¿Qué tesis de la semana ilustra?", "Una influencer cuida cada foto para parecer feliz aunque esté pasando un mal momento.", "ser y parecer se volvieron dos cosas distintas",
           ["ser y parecer se volvieron dos cosas distintas", "la piedad modera el amor de sí", "el poder frena al poder"], "*Discurso*, segunda parte: con el amor propio, el hombre sociable vive fuera de sí, en la opinión de los demás.")),
        ap(ch(2, "¿Qué ataca Rousseau?", "«La propiedad es un derecho natural, anterior a todo acuerdo, que cada uno adquiere al mezclar su trabajo con la tierra.»", "que la propiedad sea natural y no una convención",
           ["que la propiedad sea natural y no una convención", "que el trabajo sea útil", "nada: es su tesis"], "Es la tesis de Locke (semana 54). Rousseau admite que el trabajo da un derecho sobre el producto, al menos hasta la cosecha, pero la propiedad estable la hace la convención.")),
        ap(ch(2, "¿Qué es, en el *Discurso*?", "El rico propone: «unámonos para proteger a los débiles, contener a los ambiciosos y asegurar a cada uno lo suyo».", "el pacto de los ricos: un contrato ilegítimo",
           ["el pacto de los ricos: un contrato ilegítimo", "el contrato social que Rousseau defiende", "la ley natural"], "Las leyes que nacen de ahí dan «nuevas trabas al débil y nuevas fuerzas al rico» y convierten una usurpación en derecho.")),
        ch(2, "¿Quién lo dijo?", "«Todos corrieron al encuentro de sus cadenas creyendo asegurar su libertad.»", "Rousseau",
           ["Rousseau", "Hobbes", "La Boétie"], "*Discurso*, segunda parte, sobre el pacto de los ricos. La Boétie habló de «servidumbre voluntaria» en el siglo XVI, pero la frase es de Rousseau."),
        ap(ch(2, "¿Hombre de paja o crítica justa?", "«Rousseau quiere que volvamos a vivir en los bosques, en cuatro patas.»", "hombre de paja",
           ["hombre de paja", "crítica justa"], "Es la broma de Voltaire (carta del 30 de agosto de 1755). Rousseau rechaza esa conclusión en la nota IX del *Discurso*.")),
        ch(2, "Trampa.", "«El buen salvaje» es…", "una expresión que Rousseau no usa, aunque se le atribuye",
           ["una expresión que Rousseau no usa, aunque se le atribuye", "el título del *Discurso sobre la desigualdad*", "una frase de Montesquieu en las *Cartas persas*"], "La fórmula inglesa *noble savage* aparece en un drama de Dryden (1672). Con Rousseau, decir «buen salvaje» es una etiqueta de sus críticos."),
        ap(ch(2, "¿Qué diría Rousseau?", "Un economista: «la desigualdad es natural, porque la gente tiene talentos distintos».", "que las diferencias de talento no explican la desigualdad de riqueza y poder",
           ["que las diferencias de talento no explican la desigualdad de riqueza y poder", "que tiene razón", "que no hay diferencias de talento"], "La desigualdad natural se vuelve política solo con la propiedad y las instituciones; por eso pregunta si la ley natural la autoriza (y contesta que no).")),
        ap(ch(2, "¿Qué tesis ilustra *El ingenuo* (Voltaire, 1767)?", "Un joven criado entre los hurones llega a Bretaña; su franqueza choca con la hipocresía, la Iglesia y la justicia francesas, y termina preso en la Bastilla.", "que la sociedad, no la naturaleza, corrompe y oprime",
           ["que la sociedad, no la naturaleza, corrompe y oprime", "que el clima decide el carácter", "que la monarquía vive del honor"], "Voltaire se burló de Rousseau, pero su cuento usa el mismo recurso: el «natural» como juez de la civilización. Y el giro final (el hurón resulta hijo de franceses) muestra que lo decisivo fue la crianza.")),
        ap(ch(0, "¿Qué tesis ilustran?", "En las *Cartas persas*, los trogloditas se destruyen porque cada uno piensa solo en sí; sobreviven las dos familias que practican la justicia.", "que sin virtud no hay vida común posible",
           ["que sin virtud no hay vida común posible", "que el clima determina el carácter", "que el hombre natural es solitario"], "Cartas 11-14: Usbek contesta con una fábula a la pregunta de si los hombres son felices por el placer o por la virtud. Anticipa el «principio» de la república.")),
        ap(ch(2, "¿Qué tienen en común?", "Montesquieu explica las leyes por el clima, el comercio y las costumbres; Rousseau, la desigualdad por la propiedad y el amor propio.", "dos explicaciones de las instituciones por causas, no por la voluntad de Dios",
           ["dos explicaciones de las instituciones por causas, no por la voluntad de Dios", "dos defensas del despotismo", "dos teorías del contrato idénticas"], "Los dos buscan las causas naturales e históricas de lo social: es el gesto ilustrado. Rousseau agrega la pregunta por la legitimidad.")),
